                    stack.append((int(grid[i][j]), i, j))
        for op in operations:
            if len(stack) < 2:
                break
            b, bi, bj = stack.pop()
            a, ai, aj = stack.pop()
            if op == '+':
                res = a + b
            elif op == '-':
                res = a - b
            elif op == '*':
                res = a * b
            elif op == '/':
                if b == 0:
                    stack.append((a, ai, aj))
                    stack.append((b, bi, bj))
                    break
                res = a // b
            else:
